import{_ as o,o as t,c as a,ag as n}from"./chunks/framework.8tqBsFWt.js";const c=JSON.parse('{"title":"Logging time","description":"","frontmatter":{},"headers":[],"relativePath":"guide/logging-time.md","filePath":"guide/logging-time.md"}'),r={name:"guide/logging-time.md"};function s(i,e,g,h,l,d){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="logging-time" tabindex="-1">Logging time <a class="header-anchor" href="#logging-time" aria-label="Permalink to &quot;Logging time&quot;">​</a></h1><p>The simplest thing VERA does is record your hours. From the <strong>Time</strong> page in the console, logging an entry takes a few seconds.</p><hr><h2 id="logging-an-entry" tabindex="-1">Logging an entry <a class="header-anchor" href="#logging-an-entry" aria-label="Permalink to &quot;Logging an entry&quot;">​</a></h2><ol><li>Open <strong>Time</strong> in the side menu (or go straight to <a href="https://app.getvera.site/console/time" target="_blank" rel="noreferrer">app.getvera.site/console/time</a>).</li><li>Click <strong>Log time</strong>.</li><li>Choose the <strong>project</strong>, pick the <strong>task</strong> (the type of work), enter the <strong>hours</strong>, and set the <strong>date</strong>.</li><li>Save. Your entry appears in the list straight away.</li></ol><p>VERA needs a project and a duration at minimum. The date defaults to today — change it to log for a past day.</p><h3 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h3><p>The <strong>Task</strong> field is the category of work — Design, Development, Strategy, Admin, and so on. Each project has its own set of tasks enabled, so the dropdown only offers valid options. If your team has set a default task for your discipline, the modal pre-selects it; you can always change it. Internal projects (admin, training, and the like) don&#39;t require a task.</p><hr><h2 id="checking-your-hours" tabindex="-1">Checking your hours <a class="header-anchor" href="#checking-your-hours" aria-label="Permalink to &quot;Checking your hours&quot;">​</a></h2><p>The <strong>Time</strong> page lists everything you&#39;ve logged, so you can see at a glance what you&#39;ve recorded this week and spot anything missing before the day ends. Use the week controls to move between weeks and review past entries grouped by project and task.</p><hr><h2 id="fixing-a-mistake" tabindex="-1">Fixing a mistake <a class="header-anchor" href="#fixing-a-mistake" aria-label="Permalink to &quot;Fixing a mistake&quot;">​</a></h2><p>If you logged the wrong number of hours, the wrong project, or the wrong task, find the entry in the <strong>Time</strong> list and <strong>edit</strong> it. Change the values and save — the correction is immediate.</p><p>To remove an entry entirely, <strong>delete</strong> it from the same list. You&#39;ll be asked to confirm before it&#39;s removed.</p><hr><h2 id="logging-for-someone-else" tabindex="-1">Logging for someone else <a class="header-anchor" href="#logging-for-someone-else" aria-label="Permalink to &quot;Logging for someone else&quot;">​</a></h2><p>Managers and owners can log time on behalf of a team member — typically for sick days or leave. This is done from the manager&#39;s side of the console; see <a href="./time-off.html">Time off</a> for how absence is recorded.</p><hr><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>Which project do I choose?</strong> Pick it from the project dropdown in the Log time modal — every project you can log to is listed, so there&#39;s no guessing at names or spelling.</p><p><strong>What&#39;s a &quot;task&quot;?</strong> Tasks are categories of work (Design, Development, Strategy, Admin, …). Your team enables a specific set for each project, so the Task dropdown only shows valid options for the project you picked. Internal projects are task-optional.</p><p><strong>What if I forget to log for a few days?</strong> Just log them when you remember, setting the date for each entry. VERA doesn&#39;t impose time limits on past entries.</p><p><strong>I don&#39;t see a project I need to log to.</strong> Only active projects appear in the dropdown. If something&#39;s missing, ask your manager or owner — they create and manage projects from the console.</p>',24)])])}const p=o(r,[["render",s]]);export{c as __pageData,p as default};
